# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KADERLE İLİŞKİLİ KAVRAMLAR: İRADE, ÖMÜR, ECEL VE RIZIK</text>\n  <rect x="20" y="48" width="210" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. İRADE (Küllî ve Cüz\'î)</text>\n  <rect x="32" y="84" width="186" height="65" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="125" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Küllî İrade (İlahi İrade)</text>\n  <text x="125" y="120" text-anchor="middle" font-size="10" fill="#334155">Allah\'ın mutlak, sınırsız ve</text>\n  <text x="125" y="135" text-anchor="middle" font-size="10" fill="#334155">kuşatıcı dileme sıfatıdır.</text>\n  <rect x="32" y="158" width="186" height="68" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="125" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Cüz\'î İrade (İnsani Seçim)</text>\n  <text x="125" y="194" text-anchor="middle" font-size="10" fill="#334155">İnsanın akılla tercih yapma</text>\n  <text x="125" y="209" text-anchor="middle" font-size="10" fill="#334155">gücü ve sorumluluk temelidir.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. ÖMÜR VE ECEL</text>\n  <rect x="257" y="84" width="186" height="65" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="350" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Ömür (Yaşam Süresi)</text>\n  <text x="350" y="120" text-anchor="middle" font-size="10" fill="#334155">Doğumdan ölüme kadar geçen</text>\n  <text x="350" y="135" text-anchor="middle" font-size="10" fill="#334155">ve imtihan alanı olan vakittir.</text>\n  <rect x="257" y="158" width="186" height="68" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="350" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Ecel (Takdir Edilen Son)</text>\n  <text x="350" y="194" text-anchor="middle" font-size="10" fill="#334155">Hayatın sona erdiği tayin edilmiş</text>\n  <text x="350" y="209" text-anchor="middle" font-size="10" fill="#334155">andır; Ehl-i Sünnet\'e göre tektir.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. RIZIK (er-Rezzâk)</text>\n  <rect x="482" y="84" width="186" height="65" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="575" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Yaratıcı: Yüce Allah</text>\n  <text x="575" y="120" text-anchor="middle" font-size="10" fill="#334155">Tüm canlıların faydalandığı maddi</text>\n  <text x="575" y="135" text-anchor="middle" font-size="10" fill="#334155">ve manevi nimetleri Allah yaratır.</text>\n  <rect x="482" y="158" width="186" height="68" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="575" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kulun Görevi: Helal Emek</text>\n  <text x="575" y="194" text-anchor="middle" font-size="10" fill="#334155">İnsan meşru sebeplere sarılarak</text>\n  <text x="575" y="209" text-anchor="middle" font-size="10" fill="#334155">helal rızkı aramakla yükümlüdür.</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM AKAİDİNDE SAHİH TEVEKKÜL VE BAŞARI SÜRECİ</text>\n  <rect x="25" y="55" width="190" height="165" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="120" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">1. AŞAMA: FİİLÎ DUA</text>\n  <text x="120" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#0c4a6e">(Sebeplere Sarılma / Tedbir)</text>\n  <text x="120" y="128" text-anchor="middle" font-size="10.5" fill="#334155">• Planlı çalışma ve emek</text>\n  <text x="120" y="148" text-anchor="middle" font-size="10.5" fill="#334155">• Bilimsel ve teknik önlemler</text>\n  <text x="120" y="168" text-anchor="middle" font-size="10.5" fill="#334155">• Sünnetullaha tam riayet</text>\n  <text x="120" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0369a1">\'Önce deveni sağlam bağla\'</text>\n\n  <polygon points="225,130 245,130 245,122 258,135 245,148 245,140 225,140" fill="#0284c7"/>\n\n  <rect x="265" y="55" width="190" height="165" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="360" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6d28d9">2. AŞAMA: KAVLÎ DUA</text>\n  <text x="360" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#4c1d95">(Kalbi Güven ve Niyaz)</text>\n  <text x="360" y="128" text-anchor="middle" font-size="10.5" fill="#334155">• Sonucu Allah\'tan isteme</text>\n  <text x="360" y="148" text-anchor="middle" font-size="10.5" fill="#334155">• Ümitsizliğe kapılmama</text>\n  <text x="360" y="168" text-anchor="middle" font-size="10.5" fill="#334155">• İlahi yardıma (tevfik) sığınma</text>\n  <text x="360" y="196" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">\'Sonra Allah\'a tevekkül et\'</text>\n\n  <polygon points="465,130 485,130 485,122 498,135 485,148 485,140 465,140" fill="#7c3aed"/>\n\n  <rect x="505" y="55" width="170" height="165" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="590" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. AŞAMA: RIZA</text>\n  <text x="590" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">(Şükür veya Sabır)</text>\n  <text x="590" y="128" text-anchor="middle" font-size="10.5" fill="#334155">• Başarıda kibre düşmeden</text>\n  <text x="590" y="144" text-anchor="middle" font-size="10.5" fill="#334155">Allah\'a şükretme</text>\n  <text x="590" y="168" text-anchor="middle" font-size="10.5" fill="#334155">• Musibette sabredip</text>\n  <text x="590" y="184" text-anchor="middle" font-size="10.5" fill="#334155">eksikleri giderme</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EHL-İ SÜNNET AKAİDİNDE HAYIR VE ŞER DENGESİ</text>\n  <rect x="25" y="50" width="310" height="180" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#15803d">HAYIR (İyilik, İtaat ve Fayda)</text>\n  <text x="42" y="102" font-size="11" fill="#334155">• Kul cüz\'î iradesiyle iyiliği seçer (Kesb).</text>\n  <text x="42" y="124" font-size="11" fill="#334155">• Yüce Allah kudretiyle yaratır (Halk).</text>\n  <text x="42" y="146" font-size="11" fill="#334155">• İlahi emir, sevgi ve rıza vardır.</text>\n  <rect x="45" y="165" width="270" height="48" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sonuç: Kul mükâfat (sevap) kazanır;</text>\n  <text x="180" y="203" text-anchor="middle" font-size="10.5" fill="#15803d">nimeti Allah\'ın lütfu bilip şükreder.</text>\n\n  <rect x="365" y="50" width="310" height="180" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#b91c1c">ŞER (Kötülük, İsyan ve Zarar)</text>\n  <text x="382" y="102" font-size="11" fill="#334155">• Kul cüz\'î iradesiyle kötülüğü seçer (Kesb).</text>\n  <text x="382" y="124" font-size="11" fill="#334155">• İmtihan gereği Allah yaratır (Halk).</text>\n  <text x="382" y="146" font-size="11" fill="#334155">• İlahi rıza ve emir kesinlikle yoktur.</text>\n  <rect x="385" y="165" width="270" height="48" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="520" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Sonuç: Sorumluluk tamamen kula aittir;</text>\n  <text x="520" y="203" text-anchor="middle" font-size="10.5" fill="#b91c1c">\'Halk-ı şer, şer değildir; kesb-i şer, şerdir.\'</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
